// Üretilen dosya: tool/ozgun/uret.py. Mühendislik ve Tasarım · Akışkanlar mekaniği ve hidrolik (zor).
const ozEngineering7Zor = <(String, String, List<String>, String)>[
  ('İki paralel levha arasında 2 mm kalınlığında yağ vardır. Alttaki levha sabit, üstteki 0,5 m/s ile kayıyor; yağın dinamik viskozitesi 0,4 Pa·s\'dir. Hız profili doğrusal kabul edilirse kayma gerilmesi kaç Pa olur?', '100', ['0,4', '250', '1000'], 'Newton\'un viskozite yasasına göre τ = μ·(du/dy) = 0,4 × (0,5/0,002) = 0,4 × 250 = 100 Pa olur.'),
  ('Yüzey gerilimi σ olan bir su damlasının içindeki basıncın dışarıdan farkı ΔP = 2σ/R ile verilir. Yarıçapı 1 mm olan damlada σ = 0,073 N/m ise bu fark kaç pascaldır?', '146', ['73', '0,146', '1460'], 'ΔP = 2 × 0,073 / 0,001 = 146 Pa olur. Damla küçüldükçe iç basınç farkı artar.'),
  ('Bir U-borulu cıva manometresi bir hava kanalına bağlı ve öbür ucu atmosfere açık. Cıva seviyeleri arasında 15 cm fark varsa kanaldaki gösterge basıncı yaklaşık kaç kPa\'dır? (ρ_cıva = 13 600 kg/m³, g = 9,81 m/s²)', '20', ['15', '2', '136'], 'ΔP = 13 600 × 9,81 × 0,15 ≈ 20 000 Pa ≈ 20 kPa olur. Havanın yoğunluğu ihmal edilecek kadar küçüktür.'),
  ('Batık düzlem bir yüzeyde basınç merkezinin her zaman yüzeyin ağırlık merkezinden daha derinde olmasının nedeni nedir?', 'Basıncın derinlikle artması, yükün alt kısımda yoğunlaşması', ['Sıvının alt kısımda daha az yoğun olması', 'Yüzey geriliminin üst kısmı yukarı çekmesi', 'Atmosfer basıncının yalnız yüzeyin alt kısmına etkimesi ve üst kısmı boşaltması'], 'Derinlere doğru basınç büyüdüğünden bileşke kuvvet alt bölgeye kayar. Derinlik arttıkça bu kayma azalır, ama basınç merkezi ağırlık merkezinin üstüne hiç çıkmaz.'),
  ('Bir akvaryumun 0,5 m genişliğindeki ön camına, 0,6 m yüksekliğe kadar dolu sudan etkiyen toplam yatay kuvvet kaç newtondur? (ρ = 1000 kg/m³, g = 10 m/s²)', '900', ['1800', '3000', '450'], 'F = ½·ρ·g·h²·b = 0,5 × 1000 × 10 × 0,36 × 0,5 = 900 N olur.'),
  ('Hidrostatik paradoksa göre tabanları aynı alanda, içlerindeki su yüksekliği eşit; biri silindir, öteki yukarı doğru genişleyen huni biçimli iki kabın tabanına etkiyen su kuvvetleri nasıldır?', 'Eşittir, çünkü taban basıncı yalnız derinliğe bağlıdır', ['Huni biçimli kapta daha büyüktür, çünkü daha çok su vardır', 'Silindirde daha büyüktür, çünkü duvarlar düzdür', 'Huni biçimli kapta sıfırdır'], 'Taban kuvveti basınç × taban alanıdır ve basınç yalnız su yüksekliğiyle belirlenir. Fazla suyun ağırlığını eğik duvarlar taşır.'),
  ('İçinde demir bir çapa bulunan bir sandal küçük bir havuzda yüzüyor. Çapa sandaldan alınıp havuza atılırsa havuzdaki su seviyesi ne olur?', 'Biraz alçalır', ['Biraz yükselir', 'Hiç değişmez', 'Önce yükselir, sonra eski düzeyine döner'], 'Sandaldayken çapa kendi ağırlığı kadar su yer değiştirir; dipteyken yalnız kendi hacmi kadar. Demir sudan yoğun olduğu için ikinci miktar daha küçüktür ve seviye düşer.'),
  ('Kendi ekseni etrafında sabit açısal hızla döndürülen silindirik bir kaptaki suyun serbest yüzeyi hangi biçimi alır?', 'Ortası çukur bir paraboloit', ['Yatay düz bir düzlem', 'Ortası tümsek bir koni', 'Eğik düz bir düzlem'], 'Döner kapta merkezcil ivme yarıçapla arttığı için yüzey yüksekliği r² ile artar; sonuç ortası çukur dönel paraboloittir.'),
  ('Yatay doğrultuda a = 2,5 m/s² sabit ivmeyle hızlanan bir tanker kamyonundaki sıvının serbest yüzeyi yatayla hangi açıyı yapar? (g = 10 m/s²)', 'tan θ = 0,25 olan açı', ['tan θ = 4 olan açı', 'Yüzey yatay kalır', 'Tam 45°'], 'Yatay ivmeli kapta yüzey eğimi tan θ = a/g ile verilir: 2,5/10 = 0,25. Sıvı tankın arka tarafında yükselir.'),
  ('Bir ana boru 0,12 m³/s su taşıyor ve iki kola ayrılıyor. Birinci kolun kesiti 0,02 m², içindeki hız 3 m/s\'dir. İkinci koldaki debi kaç m³/s\'dir?', '0,06', ['0,12', '0,02', '0,09'], 'Birinci kolun debisi 0,02 × 3 = 0,06 m³/s\'dir. Kütle korunumuna göre ikinci kol 0,12 − 0,06 = 0,06 m³/s taşır.'),
  ('Keskin kenarlı bir delikten çıkan su jetinin kesitinin delikten biraz sonra delik kesitinden daha küçük olmasına ne ad verilir?', 'Vena contracta', ['Hidrolik sıçrama', 'Kavitasyon', 'Akış ayrılması'], 'Delik kenarına doğru yaklaşan akım çizgileri birden yön değiştiremez; jet delikten sonra daralır. Gerçek debi bu nedenle kuramsal değerin yaklaşık %60–65\'idir.'),
  ('Bir rafineride ham petrol ürünlerinin kütle debisini, yoğunluk değişse bile doğrudan ölçmek isteyen bir mühendis için en uygun ölçer hangisidir?', 'Coriolis debimetre', ['Elektromanyetik debimetre', 'Rotametre', 'Pitot tüpü'], 'Coriolis ölçerlerde titreştirilen tüpteki burulma doğrudan kütle debisiyle orantılıdır; iletkenlik gerektirmez ve yoğunluğu da ölçebilir.'),
  ('Bir su jeti düz bir levhaya çarpıp yanlara dağılmak yerine, kepçe biçimli bir yüzeyle tam 180° geri döndürülürse yüzeye etkiyen kuvvet nasıl değişir?', 'İki katına çıkar', ['Yarıya iner', 'Değişmez', 'Sıfır olur'], 'Düz levhada jetin hızı V\'den sıfıra iner; geri döndürülünce V\'den −V\'ye değişir. Momentum değişimi iki kat olduğundan kuvvet de iki katına çıkar. Pelton kepçelerinin dayandığı ilke budur.'),
  ('Kinematik viskozitesi 10⁻⁴ m²/s olan bir yağ, iç çapı 5 cm olan boruda akıyor. Akışın laminer kalması (Re < 2300) için ortalama hız en fazla yaklaşık kaç m/s olabilir?', '4,6', ['0,46', '46', '0,046'], 'V = Re·ν/D = 2300 × 10⁻⁴ / 0,05 = 4,6 m/s bulunur. Viskoz yağlar bu yüzden çoğu zaman laminer akar.'),
  ('Hagen-Poiseuille bağıntısına göre aynı basınç farkı ve aynı uzunlukta, laminer akış altında boru yarıçapı iki katına çıkarılırsa debi kaç katına çıkar?', '16', ['4', '2', '8'], 'Laminer akışta debi yarıçapın dördüncü kuvvetiyle orantılıdır (Q ∝ r⁴); 2⁴ = 16 kat artış olur.'),
  ('Damarlarda kan akışının laminer kabul edildiği durumda, bir arterin yarıçapının plakla %20 daralması akışı aynı basınçla nasıl etkiler?', 'Debi yaklaşık %59 azalır', ['Debi yaklaşık %20 azalır', 'Debi yaklaşık %40 azalır', 'Debi değişmez'], 'Q ∝ r⁴ olduğundan 0,8⁴ ≈ 0,41 olur; debi başlangıcın yaklaşık %41\'ine, yani %59 azalır. Küçük daralmaların etkisi bu yüzden büyüktür.'),
  ('Uzunluğu 100 m, çapı 0,1 m olan bir boruda su 2 m/s ile akıyor ve sürtünme katsayısı f = 0,02\'dir. Sürtünme yük kaybı kaç metredir? (g = 10 m/s²)', '4', ['0,4', '40', '2'], 'h_f = 0,02 × (100/0,1) × (2²/20) = 0,02 × 1000 × 0,2 = 4 m olur.'),
  ('Türbülanslı akışta debi ve sürtünme katsayısı sabitken boru çapı iki katına çıkarılırsa sürtünme yük kaybı yaklaşık kaçta birine düşer?', '32\'de birine', ['4\'te birine', '8\'de birine', '2\'de birine'], 'Hız V ∝ 1/D² olduğundan h_f ∝ (1/D)·V² ∝ 1/D⁵\'tir. Çap iki katına çıkınca kayıp 2⁵ = 32\'de birine iner.'),
  ('Bir depodan boruya keskin köşeli bir girişle su alınırken kayıp katsayısı yaklaşık 0,5 iken, girişin iyi yuvarlatılmasıyla bu değer 0,05\'in altına inebilir. Bunun nedeni nedir?', 'Yuvarlatılmış girişte akış kenardan ayrılmaz ve girdap bölgesi oluşmaz', ['Yuvarlatma borunun etkin çapını iki katına çıkarır ve hızı dörtte birine indirerek sürtünmeyi yok eder', 'Keskin kenarlar suyun viskozitesini artırır', 'Yuvarlatılmış girişte su daha yavaş akar'], 'Keskin köşede akım çizgileri ani dönemez; akış ayrılır, vena contracta ve enerji harcayan girdaplar oluşur. Yumuşak geçiş bunu önler.'),
  ('Paralel bağlı, aynı uzunlukta ve aynı sürtünme katsayılı iki borudan birinin çapı diğerinin iki katıdır. Türbülanslı akışta kalın borudan geçen debi ince borudakinin yaklaşık kaç katıdır?', 'Yaklaşık 5,7', ['2', '4', '32'], 'Eşit yük kaybında h_f ∝ Q²/D⁵ olduğundan Q ∝ D^2,5 olur. 2^2,5 ≈ 5,66, yani kalın boru yaklaşık 5,7 kat debi taşır.'),
  ('Joukowsky bağıntısına göre (ΔP = ρ·c·ΔV) bir boruda 1,5 m/s hızla akan su anlık olarak durdurulursa, dalga hızı 1000 m/s ise basınç artışı kaç bardır? (ρ = 1000 kg/m³)', '15', ['1,5', '150', '0,15'], 'ΔP = 1000 × 1000 × 1,5 = 1 500 000 Pa = 15 bar olur. Hızın küçük bir değişimi bile büyük basınç sıçraması yaratır.'),
  ('Joukowsky bağıntısına göre plastik (PE) borulardaki su darbesi basıncı aynı hız değişiminde çelik borulara göre neden daha düşüktür?', 'Esnek boru duvarı basınç dalgasının hızını düşürür', ['Plastik borularda su daha az yoğundur', 'Plastik borular suyu ısıtır', 'Plastik borularda akış her zaman laminerdir'], 'Dalga hızı c, su ile boru duvarının birlikte esnekliğine bağlıdır. Esnek PE duvarında c birkaç yüz m/s\'ye iner; ΔP = ρcΔV de orantılı olarak küçülür.'),
  ('1:25 ölçekli bir gemi modeli Froude benzerliğiyle deneniyor. Gerçek gemi 10 m/s hızla gidecekse model kaç m/s hızla çekilmelidir?', '2', ['0,4', '50', '10'], 'Froude benzerliğinde hız uzunluğun karekökü ile ölçeklenir: V_m = V_p/√25 = 10/5 = 2 m/s.'),
  ('Stokes yasasının geçerli olduğu bölgede küçük bir tanenin su içindeki limit çökelme hızı tane çapına nasıl bağlıdır?', 'Çapın karesiyle orantılıdır', ['Çapla ters orantılıdır', 'Çaptan bağımsızdır', 'Çapın küpüyle orantılıdır'], 'Ağırlık ve kaldırma farkı D³ ile, Stokes sürüklemesi D ile orantılıdır; dengeden V ∝ D² çıkar. Bu yüzden çok ince kil taneleri suda günlerce askıda kalır.'),
  ('Strouhal sayısı St = f·D/V yaklaşık 0,2\'dir. Çapı 0,5 m olan bir direğe 10 m/s rüzgâr çarptığında girdap kopma frekansı yaklaşık kaç Hz olur?', '4', ['1', '20', '0,4'], 'f = St·V/D = 0,2 × 10 / 0,5 = 4 Hz olur. Bu frekans yapının doğal frekansına yakınsa rezonans tehlikesi doğar.'),
  ('Manning denklemine göre bir kanalın taban eğimi dört katına çıkarılırsa (diğer her şey aynı) ortalama hız nasıl değişir?', 'İki katına çıkar', ['Dört katına çıkar', 'On altı katına çıkar', 'Yarıya iner'], 'Manning denkleminde hız eğimin karekökü ile orantılıdır; √4 = 2 olduğundan hız iki katına çıkar.'),
  ('Belirli bir kesit alanı için en az ıslak çevreye sahip, bu yüzden en büyük debiyi taşıyan \'en ekonomik\' dikdörtgen kanal kesitinde genişlik derinliğin kaç katıdır?', '2', ['1', '4', '0,5'], 'En ekonomik dikdörtgen kesitte b = 2y\'dir; hidrolik yarıçap y/2 olur. Bu oran aynı alanda sürtünme yüzeyini en aza indirir.'),
  ('Dikdörtgen bir kanalda birim genişlik başına debi q = 1 m²/s ise kritik derinlik yaklaşık kaç metredir? (y_c = (q²/g)^(1/3), g = 9,81 m/s²)', '0,47', ['1', '0,1', '0,22'], 'y_c = (1²/9,81)^(1/3) = (0,102)^(1/3) ≈ 0,467 m olur. Bu derinlikte özgül enerji en küçük değerini alır.'),
  ('Küçük debileri duyarlı biçimde ölçmek için dikdörtgen savak yerine V-çentikli (üçgen) savak tercih edilmesinin nedeni nedir?', 'Debi h^(5/2) ile değiştiği için küçük debilerde de belirgin yük farkı oluşması', ['V-çentikli savakta suyun hiç enerji kaybetmemesi', 'V-çentikli savağın çok büyük taşkınları da ölçebilmesi', 'Üçgen savağın kurulumunda yük ölçmeye gerek olmaması'], 'Üçgen çentikte akış genişliği yükle birlikte büyür; debi h^(5/2) ile orantılıdır ve az suda bile ölçülebilir bir yükseklik oluşur.'),
  ('Keskin kenarlı dikdörtgen bir savakta debi h^(3/2) ile orantılıdır. Savak üstündeki yük 4 katına çıkarsa debi kaç katına çıkar?', '8', ['4', '16', '2'], 'Q ∝ h^(3/2) olduğundan 4^(3/2) = 8 kat olur.'),
  ('Bir pompa 0,05 m³/s suyu 20 m basma yüksekliğine basıyor ve verimi %80\'dir. Mile verilmesi gereken güç kaç kW\'tır? (ρ = 1000 kg/m³, g = 10 m/s²)', '12,5', ['10', '8', '16'], 'Hidrolik güç 1000 × 10 × 0,05 × 20 = 10 000 W\'tır. Mil gücü 10 / 0,8 = 12,5 kW olur.'),
  ('Statik yükü düşük, sürtünme kayıpları baskın bir sistemde ikinci bir özdeş pompa paralel bağlanırsa debi nasıl değişir?', 'Artar, ama iki katına çıkmaz', ['Tam iki katına çıkar', 'Değişmez', 'Azalır'], 'Paralel bağlamada aynı yükte debiler toplanır; ama debi arttıkça sistemin kayıpları Q² ile yükselir ve yeni çalışma noktası iki katlık debinin altında kalır.'),
  ('Pelton türbininde kepçe çevresel hızının jet hızının yaklaşık yarısı olduğu durumda verimin en yüksek olmasının nedeni nedir?', 'Jetin çıkıştaki mutlak hızı en aza iner', ['Kepçeler bu hızda en hafif hâle gelir', 'Bu hızda kavitasyon tamamen ortadan kalkar ve su ısınmaz', 'Jet bu hızda iki katına çıkar'], 'Kepçeden geri dönen suyun mutlak hızı en küçük olduğunda kinetik enerjinin neredeyse tamamı çarka aktarılmış olur; kuramsal olarak bu, u = V/2 koşulunda gerçekleşir.'),
  ('Bir küçük hidroelektrik santral 2 m³/s debi ve 25 m net düşüyle çalışıyor; toplam verimi %80\'dir. Santral bir günde (24 saat) kaç MWh enerji üretir? (ρ = 1000 kg/m³, g = 10 m/s²)', '9,6', ['0,4', '4,8', '40'], 'P = 0,8 × 1000 × 10 × 2 × 25 = 400 000 W = 0,4 MW. Günlük enerji 0,4 × 24 = 9,6 MWh olur.'),
  ('Bir nehir tipi (biriktirmesiz) santral ile baraj göllü bir santral karşılaştırıldığında nehir tipi santralin temel kısıtı nedir?', 'Üretimin nehrin anlık debisine bağlı olması', ['Çok yüksek düşüye ihtiyaç duyması ve yalnız Pelton kullanabilmesi', 'Hiç türbin içermemesi', 'Yalnız pompaj modunda çalışabilmesi'], 'Biriktirme hacmi olmayan santral suyu depolayıp istenen saatte kullanamaz; kurak mevsimde debi düşünce üretim de düşer.'),
  ('Çift etkili, tek mil çıkışlı bir hidrolik silindirde aynı pompa debisiyle pistonun geri dönüşü ileri gidişinden neden daha hızlıdır?', 'Mil tarafındaki etkin alan daha küçüktür', ['Geri dönüşte yağın viskozitesi azalır', 'Geri dönüşte pompa devri kendiliğinden artar', 'Mil tarafındaki basınç her zaman sıfırdır'], 'Mil tarafında piston alanından mil kesiti çıkarılır; aynı debi daha küçük alana girdiğinden hız artar, ama aynı basınçla elde edilen kuvvet azalır.'),
  ('Bir vinç kolunu aşağı indirirken yükün kendi ağırlığıyla kontrolsüz düşmesini önlemek için silindirin dönüş hattına konan valf hangisidir?', 'Dengeleme (karşı denge) valfi', ['Akümülatör şarj valfi, yani gaz yastığını dolduran valf', 'Hızlı boşaltma valfi', 'Sıralama valfi'], 'Dengeleme valfi dönüş hattında yük basıncından biraz yüksek bir karşı basınç tutar; yağ ancak pompa basıncı uygulanınca boşalır ve yük denetimli iner.'),
  ('Deplasmanı 100 cm³/devir olan bir hidromotora 100 bar basınç farkı uygulanıyor. Kayıplar ihmal edilirse motorun torku yaklaşık kaç N·m\'dir?', '159', ['1000', '100', '628'], 'T = Δp·V/(2π) = 10⁷ Pa × 10⁻⁴ m³ / 6,283 ≈ 159 N·m olur.'),
  ('Daralan bir lüleden gaz akarken çıkış basıncı düşürülmeye devam edilse de kütle debisinin artmaması durumuna ne ad verilir?', 'Tıkanmış (boğulmuş) akış', ['Kavitasyon başlangıcı, yani gazın içinde kabarcıkların oluşması', 'Hidrolik sıçrama', 'Laminer geçiş'], 'Lülenin en dar kesitinde Mach 1\'e ulaşılınca aşağıdaki basınç değişimleri yukarıya iletilemez; debi yalnız giriş koşullarıyla belirlenir.'),
  ('Ses üstü hızla giden bir mermi arkasında bir Mach konisi oluşturur ve koni yarı açısı μ için sin μ = 1/M\'dir. Mermi Mach 2 ile gidiyorsa koni yarı açısı kaç derecedir?', '30', ['60', '45', '15'], 'sin μ = 1/2 olduğundan μ = 30° olur. Hız arttıkça koni daralır.'),
  ('Laminer boru akışında debinin yarıçapın dördüncü kuvvetiyle değiştiğini gösteren yasa, kan damarlarında akış üzerinde çalışan bir hekimin adıyla anılır. Bu kişi kimdir?', 'Jean Léonard Marie Poiseuille', ['William Harvey', 'Louis Pasteur', 'Claude Bernard'], 'Poiseuille 1840\'larda ince cam kılcallarla yaptığı deneylerle bu yasayı bulmuştur; Gotthilf Hagen de bağımsız olarak benzer sonuca ulaştığı için yasa Hagen-Poiseuille diye anılır.'),
  ('Ağzı kapalı, su dolu esnek bir şişenin içinde, ağzı aşağı bakan küçük bir tüpte hava kabarcığıyla yüzen \'Kartezyen dalgıç\' şişe sıkılınca batar. Bunun nedeni nedir?', 'Tüpteki hava sıkışır, yer değiştirilen hacim azalır', ['Şişe sıkılınca suyun yoğunluğu belirgin biçimde azalır ve dalgıç batar', 'Sıkma suyu ısıtır ve dalgıç ağırlaşır', 'Şişenin kapağı dalgıcı aşağı çeker'], 'Sıkmayla artan basınç Pascal ilkesiyle tüpe iletilir; içerideki hava sıkışır, tüpe su girer ve kaldırma kuvveti azalır. Bırakınca hava genişler ve dalgıç yükselir.'),
  ('Bir bardak çay karıştırılıp bırakıldığında dipteki çay yapraklarının kenara değil ortaya toplanması (çay yaprağı paradoksu) neyle açıklanır?', 'Dipteki sürtünmenin yarattığı ikincil akış', ['Çay yapraklarının sudan hafif olmasıyla', 'Merkezkaç kuvvetinin yaprakları merkeze çekmesiyle', 'Bardağın ısınıp genleşmesiyle'], 'Dipte yavaşlayan sıvı, basınç gradyanının etkisiyle merkeze doğru akar ve ortada yükselir. Bu ikincil akış yaprakları ortaya taşır; nehir kıvrımlarındaki akış da benzerdir.'),
  ('Açık bir depoda su yüksekliği H\'dir ve depo düz zeminde durmaktadır. Yan duvarda açılacak bir delikten çıkan jetin zeminde en uzağa düşmesi için delik hangi yükseklikte olmalıdır?', 'H/2', ['H/4', '3H/4', 'Tabana en yakın yerde'], 'Delik zeminden y yükseklikteyse hız √(2g(H−y)), düşüş süresi √(2y/g)\'dir; menzil 2√((H−y)y) olur ve y = H/2\'de en büyük değeri (H) alır.'),
  ('Torricelli akışıyla boşalan bir depoda boşalma süresi başlangıç yüksekliğinin kareköküyle orantılıdır. 1 m\'den 4 m\'ye yükseltilmiş bir depo, aynı delikten kaç kat daha uzun sürede boşalır?', '2', ['4', '16', '1'], 't ∝ √h olduğundan √4 = 2 kat sürer. Dört kat su vardır, ama ortalama çıkış hızı da daha büyüktür.'),
  ('Bir U-borunun bir koluna su, öbür koluna sudan hafif ve suyla karışmayan bir yağ konuyor. Yağ sütunu ara yüzeyden 20 cm yüksekte, su sütunu ise aynı ara yüzey düzeyinden 16 cm yüksekte dengede kalıyor. Yağın yoğunluğu kaç kg/m³\'tür? (ρ_su = 1000 kg/m³)', '800', ['1250', '640', '900'], 'Ara yüzey düzeyinde basınçlar eşittir: ρ_yağ × 20 = 1000 × 16, buradan ρ_yağ = 800 kg/m³ olur.'),
  ('Laminer akışta tam gelişmiş akışa ulaşmak için gereken giriş uzunluğu yaklaşık L ≈ 0,05·Re·D\'dir. Re = 1000 olan bir akışta çapı 2 cm olan boruda bu uzunluk kaç metredir?', '1', ['0,1', '10', '50'], 'L ≈ 0,05 × 1000 × 0,02 = 1 m olur. Türbülanslı akışta giriş uzunluğu genellikle 10–40 çap gibi çok daha kısadır.'),
  ('Bir boru aniden genişliyor; akış hızı 4 m/s\'den 1 m/s\'ye iniyor. Ani genişleme kaybı (V₁ − V₂)²/(2g) bağıntısıyla kaç metredir? (g = 10 m/s²)', '0,45', ['0,75', '0,8', '0,05'], 'h = (4 − 1)²/20 = 9/20 = 0,45 m olur. Bu Borda-Carnot bağıntısı momentum ve enerji denklemlerinden türetilir.'),
  ('Kısmen dolu akan dairesel bir kanalizasyon borusunda en büyük debi borunun tamamen dolu olduğu durumda değil, yaklaşık %94 doluluk dolayında görülür. Bunun nedeni nedir?', 'Tepeye yakın ıslak çevre, alandan hızlı artar', ['Tam dolu boruda su sıkışır ve debi azalır', 'Tam dolu boruda yerçekimi etkisini kaybeder', 'Tepeye yakın bölgede su ters yönde akar'], 'Son birkaç yüzdelik dilimde kesit alanı çok az artarken ıslak çevre (sürtünme yüzeyi) hızla artar; hidrolik yarıçap küçülür ve debi tam doluluğa göre biraz yüksek bir maksimumdan sonra düşer.'),
  ('Uzun bir yağ boru hattında akış laminer iken, yağ ısıtılarak viskozitesi yarıya indirilirse aynı debi için gereken pompa basıncı nasıl değişir?', 'Yaklaşık yarıya iner', ['Dört katına çıkar', 'Değişmez', 'İki katına çıkar'], 'Laminer akışta Hagen-Poiseuille bağıntısına göre basınç kaybı viskoziteyle doğru orantılıdır; viskozite yarıya inince gerekli basınç da yarıya iner. Ağır ham petrol hatlarının ısıtılmasının nedeni budur.'),
  ('Açık bir kanalda en büyük hızın genellikle tam su yüzeyinde değil, yüzeyin biraz altında görülmesinin nedeni nedir?', 'Yüzeydeki hava sürtünmesi ve ikincil akışlar', ['Yüzeyde suyun yoğunluğunun çok yüksek olması', 'Yüzeydeki suyun donmuş olması', 'Yerçekiminin yüzeyde sıfır olması'], 'Su yüzeyindeki hava direnci ve kıyı köşelerinden gelen ikincil akımlar yüzeyi bir miktar yavaşlatır; bu yüzden hız profilinin en büyük değeri yüzeyden biraz aşağıdadır.'),
  ('Hidroelektrik santrallerinde türbin kanatlarında zamanla görülen aşınmanın kavitasyon dışındaki önemli bir nedeni, özellikle dağlık bölgelerdeki nehirlerde, hangisidir?', 'Su içindeki kum ve silt taneleri', ['Suyun içindeki çözünmüş oksijenin manyetik etkisi', 'Gece ve gündüz arasındaki sıcaklık farkı', 'Ay\'ın çekim kuvveti'], 'Sertleşmiş kuvars taneleri yüksek hızda kanat yüzeyine çarparak aşındırır; Himalaya ve And bölgelerindeki santrallerde bu sorun özellikle büyüktür ve çökeltim havuzlarıyla azaltılır.'),
  ('Barajlarda yaygın kullanılan radyal (segment, Tainter) kapakların kaldırılmasının görece kolay olmasının nedeni nedir?', 'Bileşke su kuvveti döndürme mafsalından geçer', ['Su kapağı yukarı doğru iterek kendiliğinden açar', 'Kapaklar sudan hafif malzemeden yapılır ve yüzer', 'Kapaklara hiç su basıncı etkimez'], 'Kapak yüzeyi mafsal merkezli bir daire yayı olduğundan her noktadaki basınç kuvveti mafsaldan geçer; su yükü mafsala karşı moment oluşturmaz, yalnız kapak ağırlığı ve sürtünme yenilir.'),
  ('Potansiyel akış kuramı, kanat profili çevresindeki akışta basınç dağılımını iyi tahmin ederken hangi büyüklüğü tek başına hesaplayamaz?', 'Sürtünme sürüklemesini', ['Kaldırma kuvvetini', 'Durma noktasının yerini', 'Akım çizgilerinin biçimini'], 'Potansiyel akış viskoziteyi içermez; Kutta koşulu eklenince kaldırmayı doğru verir, ama yüzey sürtünmesi ve ayrılmaya bağlı sürüklemeyi veremez.'),
  ('Çok yüksek hızlı akışların görüldüğü dolusavak kanallarının tabanına hava verici düzenekler (havalandırma rampaları) konmasının amacı nedir?', 'Kavitasyon hasarını önlemek', ['Suyun hızını iki katına çıkarıp debiyi artırmak', 'Suyun donmasını önlemek', 'Balıkların oksijen ihtiyacını karşılamak'], '30 m/s\'yi aşan hızlarda basınç düşüşü betonda kavitasyon oyukları açabilir. Akışa karışan hava, çöken kabarcıkların darbesini yumuşatır; Glen Canyon Barajı\'nın 1983\'teki dolusavak hasarı sonrası yaygınlaşmıştır.'),
  ('Birbirine paralel ve yakın seyreden iki geminin birbirine doğru çekilmesinin akışkanlar mekaniğindeki nedeni nedir?', 'Aradaki dar bölgede su hızlanır, basınç düşer', ['Gemilerin manyetik gövdelerinin birbirini çekmesi', 'Gemilerin kütle çekiminin denizde büyümesi', 'Aradaki suyun donması'], 'İki gövde arasındaki su kanalda hızlanır ve basıncı düşer; dış taraflardaki daha yüksek basınç gemileri birbirine iter. 1911\'de Olympic ile HMS Hawke\'ın çarpışması bu etkiyle açıklanmıştır.'),
  ('Deplasman teknelerinde \'gövde hızı\' yaklaşık V ≈ 1,34·√L (V knot, L feet su hattı boyu) bağıntısıyla tahmin edilir. Su hattı boyu 36 feet olan bir yelkenlinin gövde hızı yaklaşık kaç knot\'tır?', '8', ['6', '48', '12'], 'V ≈ 1,34 × √36 = 1,34 × 6 ≈ 8 knot olur. Bu hızda gövdenin oluşturduğu dalga boyu tekne boyuna eşitlenir ve dalga direnci hızla artar.'),
  ('Laboratuvardaki küçük bir karıştırma tankından büyük ölçekli üretim tankına geçilirken karıştırıcı devrinin aynen korunması neden genellikle doğru değildir?', 'Ölçek büyüyünce güç ve uç hızı çok artar', ['Büyük tanklarda sıvıların viskozitesi sıfıra iner', 'Karıştırıcı devri tank boyutundan bağımsız olarak hep aynı sonucu verir', 'Büyük tanklarda yerçekimi daha zayıftır'], 'Karıştırıcı gücü yaklaşık N³D⁵ ile büyür; aynı devirde büyük çaplı çark çok fazla güç çeker ve uç hızı ürünü bozabilir. Ölçek büyütmede güç/hacim ya da uç hızı gibi ölçütler sabit tutulur.'),
  ('Rejeneratif hidrolik devrede silindirin mil tarafından çıkan yağ yeniden piston tarafına yönlendirilir. Bunun sonucu nedir?', 'İleri hareket hızlanır, kuvvet azalır', ['İleri hareket yavaşlar, kuvvet iki katına çıkar', 'Silindir hiç hareket etmez', 'Pompa debisi kendiliğinden iki katına çıkar'], 'Mil tarafından gelen yağ pompa debisine eklenir; piston tarafında etkin alan yalnız mil kesiti kadar kalır. Bu yüzden hız artar ama itme kuvveti mil alanına düşer; preslerde hızlı yaklaşma için kullanılır.'),
  ('Hidrolik silindirlerde strok sonuna yaklaşırken çıkış yağının dar bir yoldan geçmeye zorlanmasıyla pistonun yavaşlatılmasına ne ad verilir ve amacı nedir?', 'Yastıklama; darbeyi önlemek', ['Rejenerasyon; hızı artırmak', 'Kavitasyon; yağı soğutmak', 'Alma (priming); havayı atmak'], 'Yastıklama bölgesinde dışarı çıkan yağ kısıldığı için piston frenlenir; silindir kapağına sert çarpma, gürültü ve yapısal hasar önlenir.'),
  ('Bir enjeksiyon makinesinin konum ve hızının elektrik sinyaliyle çok hassas ve hızlı denetlenmesi isteniyor. Hangi valf türü en uygundur?', 'Servo valf', ['Elle kumandalı 4/3 yön valfi', 'Çek valf, yani yalnız tek yönlü geçiş sağlayan valf', 'Emniyet valfi'], 'Servo valfler küçük elektrik sinyaliyle sürgüyü orantılı ve çok hızlı konumlandırır; kapalı döngü denetimle yüksek hassasiyet sağlar, ama kirliliğe karşı çok duyarlıdırlar.'),
  ('Dikdörtgen bir kanalda belirli bir debi ve kritik derinlikten büyük özgül enerji için kaç farklı akış derinliği mümkündür?', 'İki: biri kritik altı, biri kritik üstü', ['Yalnız bir, o da her zaman kritik derinliktir', 'Sonsuz sayıda', 'Hiç yoktur, akış durur'], 'Özgül enerji eğrisinde aynı E değerine iki derinlik (eşlenik olmayan \'alternatif derinlikler\') karşılık gelir: yavaş ve derin akış ile hızlı ve sığ akış. Kapak altından geçişte akış birinden ötekine geçer.'),
  ('Dikdörtgen bir kanalda kritik derinlik 0,6 m\'dir. Bu kanaldaki en küçük özgül enerji kaç metredir? (Dikdörtgen kesitte E_min = 1,5·y_c)', '0,9', ['0,6', '1,2', '0,4'], 'Kritik derinlikte hız yükü derinliğin yarısına eşittir; E_min = y_c + y_c/2 = 1,5 × 0,6 = 0,9 m olur.'),
  ('Bir nehre baraj ya da savak yapıldığında suyun memba tarafında yapının çok gerisine kadar yükselmesine ne ad verilir?', 'Kabarma (remu) eğrisi', ['Hidrolik sıçrama, yani hızlı akıştan yavaş akışa ani geçiş', 'Su darbesi', 'Kritik akış'], 'Yapı derinliği artırır; kritik altı akışta bu etki membaya doğru yayılır ve su yüzeyi kilometrelerce geriye kadar kabarabilir. Köprü ve taşkın planlamasında hesaplanır.'),
  ('Kritik üstü (hızlı) bir akışta kanal tabanında küçük bir yükselti (eşik) bulunursa su yüzeyi bu yükseltinin üstünde nasıl davranır?', 'Yükselir', ['Alçalır, çünkü su eşiğin üstünde hızlanır', 'Hiç değişmez', 'Su eşiğin üstünde durur ve geriye akar'], 'Özgül enerji eğrisine göre kritik üstü akışta taban yükselince derinlik artar ve su yüzeyi kabarır; kritik altı akışta ise aynı eşik üstünde su yüzeyi alçalır.'),
  ('Bir sabun köpüğünün iki yüzeyi olduğundan iç basınç farkı ΔP = 4σ/R\'dir. Yarıçapı 2 cm olan bir köpükte σ = 0,025 N/m ise bu fark kaç Pa\'dır?', '5', ['2,5', '10', '0,5'], 'ΔP = 4 × 0,025 / 0,02 = 0,1/0,02 = 5 Pa olur. Tek yüzeyli damladan farklı olarak köpükte ince zarın iki yüzeyi vardır.'),
  ('Bir boru akışındaki basınç kaybı ΔP; yoğunluk ρ, hız V, çap D, viskozite μ, uzunluk L ve pürüzlülük ε\'ye bağlıdır. Buckingham Pi teoremine göre kaç bağımsız boyutsuz grup elde edilir?', '4', ['3', '7', '6'], '7 değişken (ΔP dahil) ve 3 temel boyut (M, L, T) vardır; 7 − 3 = 4 grup çıkar: Euler sayısı, Reynolds sayısı, L/D ve ε/D.'),
  ('Kesiti 10 cm² olan keskin kenarlı bir delik, serbest yüzeyin 5 m altındadır. Debi katsayısı 0,6 ise debi kaç L/s olur? (g = 10 m/s²)', '6', ['10', '0,6', '60'], 'Kuramsal hız √(2 × 10 × 5) = 10 m/s; Q = C_d·A·V = 0,6 × 0,001 × 10 = 0,006 m³/s = 6 L/s olur.'),
  ('Bir deliğin dışına deliğin çapının 2–3 katı uzunlukta kısa silindirik bir ağızlık takılınca debinin arttığı görülür. Bunun nedeni nedir?', 'Daralmış kesitte basınç atmosferin altına iner', ['Ağızlık suyun viskozitesini azaltır', 'Ağızlık depodaki su yüksekliğini artırır', 'Ağızlık jetin hızını tam iki katına çıkarır'], 'Ağızlık içinde jet daralır sonra boruyu doldurur; daralma kesitinde oluşan vakum etkin yükü artırır. Debi katsayısı yaklaşık 0,6\'dan 0,8 dolaylarına çıkar.'),
  ('Uzunluğu 1500 m olan bir boru hattında basınç dalgasının hızı 1000 m/s\'dir. Vananın \'ani kapanma\' sayılmaması için kapanma süresi en az kaç saniyeden uzun olmalıdır? (Kritik süre 2L/c)', '3', ['1,5', '0,67', '30'], 'Dalga vanadan depoya gidip dönmek için 2L/c = 2 × 1500 / 1000 = 3 s\'ye ihtiyaç duyar; bundan kısa kapanışlarda tam Joukowsky basıncı oluşur.'),
  ('Bir pompa aniden durduğunda uzun bir terfi hattının pompaya yakın bölümünde önce basınç düşmesi ve suyun kolon hâlinde kopması tehlikesi doğar. Buna ne ad verilir?', 'Su kolonu ayrılması', ['Hidrolik sıçrama, yani sığdan derine geçiş', 'Kılcal yükselme', 'Laminer geçiş'], 'Pompa durunca su ataletiyle hattın ilerisine akmaya devam eder, pompa tarafında basınç buhar basıncına iner ve boşluk oluşur. Kolonlar yeniden birleşirken çok büyük basınç darbeleri meydana gelir.'),
  ('Bir kontrol vanasında büyük basınç düşüşü olduğunda vanada gürültü ve iç yüzeyde aşınma görülüyor. En olası neden hangisidir?', 'Daralan kesitte kavitasyon', ['Akışkanın donması', 'Vananın paslanmaz çelikten yapılmış olması', 'Akışın laminer olması'], 'Vana boğazında hız artar, basınç buhar basıncının altına iner; vanadan sonra basınç toparlanınca kabarcıklar çöker. Çok kademeli basınç düşürme ya da kavitasyona dayanıklı vana iç takımları kullanılır.'),
  ('Bir kanalda düşey sürgülü bir kapağın altından akış: memba derinliği 2 m, kapak açıklığı küçük ve akış katsayısı 0,6 ise birim genişlik başına debi yaklaşık q = C·a·√(2g·y₁) ile verilir. Kapak açıklığı a = 0,5 m için q kaç m²/s\'dir? (g = 10 m/s²)', '1,9', ['3,2', '0,6', '6,3'], '√(2 × 10 × 2) = √40 ≈ 6,32 m/s; q = 0,6 × 0,5 × 6,32 ≈ 1,9 m²/s olur.'),
  ('Kesiti 0,002 m² olan bir su jeti 20 m/s hızla, aynı yönde 5 m/s hızla uzaklaşan düz bir levhaya dik çarpıyor. Levhaya etkiyen kuvvet kaç N\'dir? (ρ = 1000 kg/m³)', '450', ['800', '600', '200'], 'Levhaya göre bağıl hız 15 m/s\'dir; levhaya ulaşan kütle debisi ρA(V−u) = 1000 × 0,002 × 15 = 30 kg/s. Kuvvet 30 × 15 = 450 N olur.'),
  ('Aynı ön alana sahip düz bir disk ile damla biçimli bir gövde aynı hızda karşılaştırılırsa sürükleme kuvvetleri arasındaki fark yaklaşık ne düzeydedir?', 'Disk çok daha fazla, onlarca kat', ['İkisi tam olarak eşittir', 'Damla biçimli gövde diskin iki katı', 'Disk yalnızca yüzde birkaç fazla'], 'Akışa dik diskin C_d değeri yaklaşık 1,1–1,2 iken iyi akım hatlı bir gövdede 0,05 civarına iner; iz bölgesi neredeyse ortadan kalktığı için fark onlarca kattır.'),
  ('Kütlesi 80 kg olan bir paraşütçünün paraşütü açıkken C_d·A çarpımı 40 m²\'dir. Hava yoğunluğu 1,2 kg/m³ ise limit hızı yaklaşık kaç m/s\'dir? (g = 10 m/s²)', '5,8', ['3,3', '33', '10'], 'Limit hızda mg = ½ρV²·C_d·A: V = √(2 × 800 / (1,2 × 40)) = √33,3 ≈ 5,8 m/s olur.'),
  ('Yarıçapı 0,1 mm, yoğunluğu 2650 kg/m³ olan bir kum tanesi 20 °C suda (μ = 10⁻³ Pa·s) çöküyor. Stokes bağıntısı V = 2(ρ_t − ρ_s)·g·r²/(9μ) ile limit hızı yaklaşık kaç mm/s\'dir? (g = 10 m/s²)', '37', ['3,7', '370', '0,37'], 'V = 2 × 1650 × 10 × 10⁻⁸ / (9 × 10⁻³) ≈ 0,0367 m/s ≈ 37 mm/s olur. (Bu tane boyutunda Re ~ 7 olduğundan gerçek hız biraz daha düşüktür.)'),
  ('Yüksek hızla uçan bir uçağın burnundaki durma noktasında hava sıcaklığı T₀ = T + V²/(2c_p) kadar yükselir. Ortam −50 °C, hız 250 m/s ve c_p = 1000 J/(kg·K) ise durma sıcaklığı yaklaşık kaç °C\'dir?', '−19', ['−50', '+31', '−44'], 'V²/(2c_p) = 62 500/2000 ≈ 31 K\'dir; T₀ ≈ −50 + 31 = −19 °C olur. Uçak sıcaklık algılayıcıları bu yüzden \'toplam hava sıcaklığı\' ölçer.'),
  ('Toprak bir baraj gövdesi ya da temelinden sızan suyun ince taneleri sürükleyerek giderek genişleyen bir kanal açması ve barajı içten oyması olayına ne ad verilir?', 'Borulanma', ['Kavitasyon', 'Sıvılaşma, yani depremde zeminin taşıma gücünü yitirmesi', 'Kabarma'], 'Sızma hızı belirli bir eşiği aşınca çıkış yüzeyindeki taneler taşınır, oyuk membaya doğru ilerler ve kısa sürede baraj yıkılabilir. 1976\'da ABD\'deki Teton Barajı\'nın çöküşü bunun bilinen örneklerindendir.'),
  ('Toprak barajlarda mansap tarafındaki sızma çıkış bölgesine dereceli kum-çakıl filtreleri ve drenler konmasının amacı nedir?', 'Suyu geçirip taneleri tutmak', ['Sızan suyu tekrar göle pompalamak', 'Gövdenin ağırlığını azaltmak', 'Suyu ısıtarak buharlaştırmak'], 'Dereceli filtre suyu düşük basınçla güvenle dışarı alır ama gövde taneciklerinin taşınmasına izin vermez; böylece borulanma ve şev kaymaları önlenir.'),
  ('Bir tankın tabanındaki basıncı ölçerek sıvı seviyesini bulan hidrostatik seviye ölçerler hangi durumda hatalı sonuç verir?', 'Sıvının yoğunluğu değişirse', ['Tankın genişliği değişirse', 'Tank yüksek bir binada ise', 'Tankın rengi değişirse'], 'Ölçülen basınç P = ρgh\'dir; seviye h = P/(ρg) ile hesaplanır. Yoğunluk sıcaklık ya da bileşim nedeniyle değişirse aynı basınç farklı bir seviyeye karşılık gelir.'),
  ('Duş açıldığında duş perdesinin içeri doğru, insanın bacaklarına yapışacak biçimde gelmesinin en kabul gören açıklaması nedir?', 'Su püskürmesinin oluşturduğu girdabın içerideki basıncı düşürmesi', ['Perdenin sıcak suyla genleşip ağırlaşması', 'Duş kabinindeki suyun perdeyi kılcallıkla emmesi', 'Perdenin statik elektrikle yüklenip suya çekilmesi'], 'Bilgisayar benzetimleri, püsküren damlaların kabin içinde düşey eksenli bir girdap oluşturduğunu ve girdap merkezindeki düşük basıncın perdeyi içeri çektiğini göstermiştir; sıcak havanın yükselmesi de katkı verebilir.'),
  ('Bir santrifüj pompa su yerine yoğunluğu 1,2 kat fazla bir tuz çözeltisi basarsa (viskozite benzer) basma yüksekliği ve mil gücü nasıl değişir?', 'Yükseklik aynı kalır, güç 1,2 kat artar', ['İkisi de değişmez', 'Yükseklik 1,2 kat artar, güç değişmez', 'Yükseklik ve güç 1,44 kat artar'], 'Santrifüj pompa sıvıya belirli bir enerji/kütle verir; metre sıvı cinsinden yükseklik yoğunluktan bağımsızdır. Güç ρgQH ile orantılı olduğundan yoğunlukla birlikte artar, basınç da öyle.'),
  ('Bir pompa emme deposundan 30 m yüksekteki depoya su basıyor. Emme ve basma hatlarındaki toplam kayıp 6 m\'dir. Pompanın sağlaması gereken toplam basma yüksekliği kaç metredir?', '36', ['24', '30', '6'], 'Toplam yükseklik = statik kot farkı + kayıplar = 30 + 6 = 36 m olur.'),
  ('Bir pompa atmosfere açık bir depodan su emiyor. Atmosfer basıncı 10,3 m su, suyun buhar basıncı 0,3 m su, emme kayıpları 1 m\'dir ve pompa ekseni su yüzeyinin 4 m üstündedir. Mevcut NPSH kaç metredir?', '5', ['6', '4', '15'], 'NPSH_mevcut = 10,3 − 0,3 − 1 − 4 = 5 m olur; pompanın gerektirdiği NPSH bundan küçükse kavitasyon olmaz.'),
  ('Bir petrol rafinerisinde kum ve tortu içeren ağır bir ham petrolün kesintisiz ve düzgün debiyle taşınması gerekiyor. Hangi pompa türü en uygundur?', 'İlerleyen boşluklu (helisel rotorlu) pompa', ['Yüksek devirli çok kademeli santrifüj pompa', 'Eksenel pervane pompası', 'Yüksek basınçlı pistonlu dozaj pompası'], 'Kauçuk bir statorda dönen helis rotor sürekli ilerleyen boşluklar oluşturur; viskoz, katı içeren ve kesilmeye duyarlı akışkanları darbesiz ve düzgün taşır.'),
  ('Bir boru hattında 1 noktasında basınç 200 kPa, hız 2 m/s, kot 0 m; 2 noktasında hız 2 m/s, kot 10 m\'dir. Kayıplar ihmal edilirse 2 noktasındaki basınç kaç kPa\'dır? (ρ = 1000 kg/m³, g = 10 m/s²)', '100', ['200', '300', '120'], 'Hızlar eşit olduğundan kinetik terimler sadeleşir: P₂ = P₁ − ρg(z₂ − z₁) = 200 − 100 = 100 kPa.'),
  ('Kayıpsız bir sistemde enerji çizgisi yatay kalır. Gerçek bir boru hattında ise enerji çizgisi akış yönünde nasıl davranır?', 'Sürekli alçalır, pompalarda yükselir', ['Sürekli yükselir', 'Her zaman boru ekseniyle çakışır', 'Akış yönünden bağımsız olarak sabittir'], 'Sürtünme ve yerel kayıplar mekanik enerjiyi azaltır; enerji çizgisi akış boyunca aşağı eğimlidir. Pompa noktalarında enerji eklendiği için aniden yükselir, türbinlerde ise düşer.'),
  ('Francis türbininin dönen çarkının çok yüksekte (kuyruk suyu seviyesinin çok üstünde) yerleştirilmesi neden sakıncalıdır?', 'Çıkışta basınç düşer, kavitasyon olur', ['Su türbine hiç ulaşamaz', 'Türbin ters yönde dönmeye başlar', 'Jeneratör frekansı artar'], 'Çark ne kadar yüksekteyse emme borusu boyunca basınç o kadar düşer; buhar basıncının altına inen bölgelerde kavitasyon başlar. Büyük santrallerde çark çoğunlukla kuyruk suyu seviyesinin altına yerleştirilir.'),
  ('Bir beton kanalda (n = 0,015) hidrolik yarıçap 1 m, taban eğimi 0,0009\'dur. Manning denklemine göre ortalama hız kaç m/s\'dir?', '2', ['1,5', '0,9', '3'], 'V = (1/n)·R^(2/3)·S^(1/2) = (1/0,015) × 1 × 0,03 = 2 m/s olur.'),
  ('Tamamen su altında seyreden bir denizaltının direnci model deneyiyle incelenirken Froude yerine Reynolds benzerliğinin esas alınmasının nedeni nedir?', 'Serbest yüzey dalgası oluşmaz', ['Denizaltılar her zaman ses üstü hızda gider', 'Su altında viskozite sıfırdır', 'Denizaltı modelleri yalnız havada denenebilir'], 'Derinde ilerleyen gövde serbest yüzeyde dalga oluşturmadığı için yerçekimi etkisi önemsizdir; direnç esas olarak viskoz kuvvetlere bağlıdır ve Reynolds sayısı eşleştirilir.'),
  ('Bir dolusavak 1:36 ölçekli modelde Froude benzerliğiyle deneniyor. Modelde ölçülen debi 0,05 m³/s ise prototipteki debi kaç m³/s\'dir? (Debi ölçeği L^(5/2))', '388,8', ['1,8', '64,8', '10 800'], 'Froude benzerliğinde debi oranı L^(5/2)\'dir: 36^(2,5) = 6⁵ = 7776. Prototip debisi 0,05 × 7776 = 388,8 m³/s olur.'),
  ('Geniş bir açık kanalda tabandaki ortalama kayma gerilmesi τ = ρ·g·R·S ile hesaplanır. Hidrolik yarıçap 2 m, taban eğimi 0,0005 ise kayma gerilmesi kaç Pa\'dır? (ρ = 1000 kg/m³, g = 10 m/s²)', '10', ['1', '100', '0,5'], 'τ = 1000 × 10 × 2 × 0,0005 = 10 Pa olur. Bu gerilme taban malzemesinin taşınıp taşınmayacağını belirlemekte kullanılır.'),
  ('Havada (ν = 1,5×10⁻⁵ m²/s) 30 m/s hızla giden, boyu 4,5 m olan bir otomobilin uzunluğa dayalı Reynolds sayısı yaklaşık kaçtır?', '9×10⁶', ['9×10⁴', '2×10⁵', '3×10⁸'], 'Re = VL/ν = 30 × 4,5 / 1,5×10⁻⁵ = 9×10⁶ olur. Taşıt akışları bu yüzden neredeyse her zaman türbülanslıdır.'),
  ('Düz bir levha üzerinde laminer sınır tabaka kalınlığı yaklaşık δ ≈ 5x/√Re_x ile verilir. x = 1 m\'de Re_x = 250 000 ise sınır tabaka kalınlığı kaç mm\'dir?', '10', ['1', '50', '0,5'], '√250 000 = 500; δ ≈ 5 × 1 / 500 = 0,01 m = 10 mm olur.'),
  ('Kanadın kaldırma kuvvetini \'üstten giden hava alttakiyle firar kenarında aynı anda buluşmak için daha hızlı gitmelidir\' diye açıklayan yaygın anlatım için hangisi doğrudur?', 'Yanlıştır; üstteki hava genellikle daha önce varır', ['Tamamen doğrudur ve kaldırmanın tek nedenidir', 'Yalnızca ses üstü hızlarda doğrudur', 'Yalnızca simetrik profillerde doğrudur'], 'Eşit süre varsayımının fiziksel bir dayanağı yoktur; deneyler üstteki havanın firar kenarına alttakinden önce ulaştığını gösterir. Kaldırma, profilin akışı aşağı saptırması ve sirkülasyonla açıklanır.'),
  ('Pascal\'ın fıçı deneyi olarak anlatılan gösteride, su dolu sağlam bir fıçının kapağına takılan çok ince ve uzun bir boruya birkaç bardak su dökülünce fıçının çatlaması neyi gösterir?', 'Basınç sıvının miktarına değil yüksekliğine bağlıdır', ['Su sıkıştırılınca hacmi çok artar', 'İnce borular suyu hızlandırır ve fıçıyı ısıtır', 'Fıçının tahtası suyu emip şişer'], 'Birkaç bardak su ince boruda metrelerce yükseklik oluşturur; tabandaki ve kapaktaki basınç ρgh kadar artar ve fıçının geniş yüzeylerine çok büyük kuvvet uygular.'),
  ('Hacmi 1000 m³ olan bir helyum balonu deniz seviyesindeki havada (ρ = 1,2 kg/m³) duruyor. Helyumun yoğunluğu 0,17 kg/m³ ise balonun zarf, sepet ve yük olarak taşıyabileceği en büyük kütle yaklaşık kaç kg\'dır?', '1030', ['1200', '170', '1370'], 'Kaldırma ile helyum ağırlığı arasındaki fark taşınabilecek kütleyi verir: (1,2 − 0,17) × 1000 = 1030 kg.'),
  ('Bir vananın açılmasından hemen sonra boruda debinin artmaya devam ettiği kısa süre için akış nasıl sınıflandırılır?', 'Daimi olmayan', ['Daimi ve üniform', 'Daimi ama üniform olmayan', 'Sıkıştırılabilir ve ses üstü'], 'Vana açıldıktan sonra su kolonu ivmelenirken her noktadaki hız zamanla değişir; akış ancak yeni denge kurulunca daimi hâle gelir.'),
  ('Hız farklı iki akışkan katmanının ara yüzeyinde dalgaların büyüyüp kıvrılarak girdaplara dönüştüğü, bulutlarda deniz dalgası gibi görülen kararsızlığa ne ad verilir?', 'Kelvin-Helmholtz kararsızlığı', ['Rayleigh-Taylor kararsızlığı, yani ağır akışkanın hafifin üstünde durması', 'Kármán girdap yolu', 'Hidrolik sıçrama'], 'Kayma katmanında küçük dalgalanmalar basınç farklarıyla büyür ve kıvrılır; rüzgârın su yüzeyinde dalga oluşturması da aynı kararsızlıkla başlar.'),
  ('Kapalı devre bir ısıtma sisteminde (su bir döngüde dolaşıyor) sirkülasyon pompasının basma yüksekliği hesabında binanın yüksekliği neden hesaba katılmaz?', 'Gidiş ve dönüşteki kot farkları birbirini dengeler', ['Kapalı devrede su yerçekiminden etkilenmez', 'Kapalı devrede sürtünme kaybı yoktur', 'Pompa yalnız en alt katı besler'], 'Kapalı döngüde su yükselen kolda kazandığı potansiyel enerjiyi inen kolda geri kazanır; pompa yalnız boru, radyatör ve vanalardaki sürtünme kayıplarını karşılar.'),
  ('Beton dolusavakların tepe kısmının, üstünden aşan su tabakasının alt yüzeyini izleyecek biçimde (ogee profili) yapılmasının amacı nedir?', 'Yüzeyde negatif basınç ve kavitasyon oluşmasını önlemek', ['Suyun hızını sıfıra indirmek', 'Dolusavaktan geçen debiyi azaltmak', 'Balıkların dolusavaktan geçmesini kolaylaştırmak'], 'Serbestçe düşen su tabakasının alt yüzeyine uygun biçimlenen tepe üzerinde basınç atmosfere yakın kalır; tepe daha dik olsaydı su yüzeyden ayrılıp düşük basınç bölgeleri oluşurdu.'),
  ('Dikdörtgen bir kanalda hidrolik sıçramadan önceki Froude sayısı 3 ise sıçrama sonrası derinliğin önceki derinliğe oranı Bélanger bağıntısına göre [½(√(1+8Fr²) − 1)] yaklaşık kaçtır?', '3,8', ['3', '9', '1,5'], '√(1 + 8 × 9) = √73 ≈ 8,54; oran ½(8,54 − 1) ≈ 3,77 olur.'),
  ('Bir CFD analizinde \'ağdan bağımsızlık\' denetimi nasıl yapılır?', 'Ağ sıklaştırılıp sonuçların artık değişmediği gösterilir', ['Ağ seyrekleştirilip hesap süresi kısaltılır', 'Farklı renk ölçekleriyle grafikler çizilir', 'Sınır koşulları rastgele değiştirilir'], 'Hücre sayısı aşama aşama artırılarak sürükleme, basınç düşüşü gibi büyüklükler karşılaştırılır; değişim ihmal edilebilir düzeye inince sonuçların ağ yapısından bağımsız olduğu kabul edilir.'),
];
